-- GENERATED by `wfj generate` from data/spell/spell-0401.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("spell", {
  [401417] = { "Cura il bersaglio di $N1 salute in $D1 e applica Temporal Beacon per $D2.\n\nTemporal Beacon\n$I1\nRegistra la posizione spazio-temporale del soggetto. Il $N4% di tutti i danni da arcano inflitti dall'incantatore viene convertito in cure cronomantiche su ciascuno dei bersagli attuali di Temporal Beacon dell'incantatore. Questa cura è ridotta del $N5% su sé stessi, e ridotta anche del $N6% quando i danni sono inflitti da incantesimi arcani che colpiscono più bersagli.", { "Cura di $N1 salute in $D1. Velocità di movimento aumentata del $N3%.", "Cura di $N1 salute in $D1.", shape = { "3/1", "2/1" } }, 0x7470eeff, 0x931e594a, "uu" },
  [401460] = { "Cura il bersaglio di $N1 salute in $D1 e applica Temporal Beacon per $D2.\n\n$I1\nRegistra la posizione spazio-temporale del soggetto. Il $N4% di tutti i danni da arcano inflitti dall'incantatore viene convertito in cure cronomantiche su ciascuno dei bersagli attuali di Temporal Beacon dell'incantatore. Questa cura è ridotta del $N5% su sé stessi, e ridotta anche del $N6% quando i danni sono inflitti da incantesimi arcani che colpiscono più bersagli.", "Cura di $N1 salute in $D1.", 0x5178d77e, 0x71292dfd, "uu" },
  [401462] = { "Il tuo bersaglio attuale con Temporal Beacon guarisce istantaneamente tutti i danni subiti negli ultimi $N1 s. Inefficace sui bersagli che non avevano Temporal Beacon $N2 s prima.", nil, 0x490806a3, nil, "um" },
  [401488] = { "Incidi sui tuoi gambali la runa Assalto d'Ombra:\n\n$I1\nTi teletrasporti alle spalle del bersaglio e lo colpisci, infliggendo il $N1% dei danni dell'arma. Utilizzabile solo in Furtività. Fornisce $N2 punti combo.", nil, 0x2b51ff0b, nil, "um" },
  [401502] = { "Scaglia un dardo di fuocogelo contro il nemico, infliggendo $N1 danni da fuocogelo, rallentandone la velocità di movimento del $N2% e infliggendo altri $N3 danni da fuocogelo in $D1. Per questo incantesimo vale la più bassa tra le resistenze al gelo e al fuoco del bersaglio, e conta sia come danni da gelo sia come danni da fuoco.", "Velocità di movimento ridotta del $N1%. $N2 danni da fuocogelo ogni $D1.", 0xff979685, 0x3991e2af, "uu" },
  [401556] = { "Evoca una fiamma di fuocoincanto che si muove verso il bersaglio, lasciando una scia di fuocoincanto. La scia infligge $N1 danni da fuocoincanto al secondo ai nemici vicini. Dura $D1.", nil, 0xb96c469d, nil, "um" },
  [401558] = { "Infligge $N1 danni da fuoco ogni $D1.", "Infligge $N1 danni da fuoco ogni $D1.", 0x5c2b23fa, 0xe0649799, "uu" },
  [401617] = { "Dissotterra il tesoro nel punto segnato", nil, 0xcb9fbb49, nil, "um" },
  [401681] = { "Decifra gli appunti dell'incantesimo con un Comphrehension Primer per apprendere un nuovo incantesimo d'incisione.", nil, 0x1278ff25, nil, "um" },
  [401683] = { "Tenta di tradurre gli appunti dell'incantesimo in una nuova ricetta d'incisione runica.", nil, 0x68ecd2ae, nil, "um" },
  [401684] = { "Tenta di tradurre gli appunti dell'incantesimo in una nuova ricetta d'incisione runica.", nil, 0x68ecd2ae, nil, "um" },
  [401699] = { "Combina $N1 Azora Apprentice Notes per scoprire una nuova ricetta d'incisione runica.", nil, 0x0d2429ee, nil, "um" },
  [401719] = { "Ottieni l'abilità Sbarramento Arcano:\n\n$I1\nScaglia diversi missili contro il nemico bersaglio, infliggendo $N1 danni da arcano. Questo incantesimo ha anche una probabilità del $N2% di attivare Raffica di Missili.", nil, 0x5cc6b146, nil, "um" },
  [401722] = { "Incidi sul tuo mantello la runa Sbarramento Arcano:\n\n$I1\nScaglia diversi missili contro il nemico bersaglio, infliggendo $N1 danni da arcano. Questo incantesimo ha anche una probabilità del $N2% di attivare Raffica di Missili.", nil, 0x948d9b5e, nil, "um" },
  [401724] = { "Ottieni l'abilità Serie Bollente:\n\n$I1\nI colpi critici non periodici di Palla di Fuoco, Palla di Fuocogelo, Detonazione di Fuoco e Bruciatura riducono del $N2% il tempo di lancio della tua prossima Pirosfera lanciata entro $D1, effetto che si accumula fino a $N3 volte. Detonazione di Fuoco conferisce un accumulo aggiuntivo ogni volta che infligge danni.", nil, 0x03e95487, nil, "um" },
  [401725] = { "Ottieni l'abilità Mente Fredda:\n\n$I1\nI tuoi incantesimi che infliggono danni da gelo con effetti di raggelamento hanno una probabilità del $N1% di rendere istantaneo e senza costo in mana il tuo prossimo incantesimo Palla di Fuoco, Dardo di Geloincanto, Balefire Bolt o Palla di Fuocogelo.", nil, 0x7ed1f1da, nil, "um" },
  [401726] = { "Ottieni l'abilità Advanced Warding:\n\n$I1\nI tuoi incantesimi Scudo di Mana, Protezione dal Gelo e Guardia di Fuoco ora possono essere lanciati su qualsiasi bersaglio amico e assorbono il $N1% di danni in più, e Scudo di Mana consuma il $N2% di mana in meno per ogni danno assorbito. Inoltre, il tuo Remove Lesser Curse è sostituito da Remove Greater Curse.\n\n$I2\nRimuove $N3 maledizione e $N4 effetto magico dannoso da un bersaglio amico.", nil, 0x3b37264b, nil, "um" },
  [401729] = { "Ottieni l'abilità ⟦Arcane Blast=Detonazione Arcana⟧:\n\n$I1\nInveste il bersaglio con un'esplosione di energia, infliggendo $N1 danni da arcano. Ogni volta che lanci ⟦Arcane Blast=Detonazione Arcana⟧, ottieni il $N2% del tuo Intelletto come danni magici e il costo in mana di ⟦Arcane Blast=Detonazione Arcana⟧ aumenta del $N3%. L'effetto si accumula fino a $N4 volte e dura $D1 dalla prima applicazione.", nil, 0x6a8d4cac, nil, "um" },
  [401731] = { "Ottieni l'abilità ⟦Living Bomb=Bomba Vivente⟧:\n\n$I1\nIl bersaglio diventa una ⟦Living Bomb=Bomba Vivente⟧ e subisce $N1 danni da fuoco in $D1. Dopo $D2 o quando l'incantesimo viene dissolto, il bersaglio esplode infliggendo $N4 danni da fuoco a tutti i nemici entro $N5 m.\n\n⟦Living Bomb=Bomba Vivente⟧ beneficia di tutti i talenti e gli effetti che si attivano da Bruciatura o la modificano.", nil, 0x395d18dc, nil, "um" },
  [401732] = { "Ottieni l'abilità Lancia di Ghiaccio:\n\n$I1\nInfligge $N1 danni da gelo a un nemico bersaglio. Infligge il $N2% di danni in più ai bersagli congelati.", nil, 0xee304a05, nil, "um" },
  [401734] = { "Ottieni l'abilità Riavvolgimento Temporale:\n\n$I1\nIl tuo bersaglio attuale con Temporal Beacon guarisce istantaneamente tutti i danni subiti negli ultimi $N1 s. Inefficace sui bersagli che non avevano Temporal Beacon $N2 s prima.", nil, 0x6a873727, nil, "um" },
  [401735] = { "Ottieni l'abilità Palla di Fuocogelo:\n\n$I1\nScaglia un dardo di fuocogelo contro il nemico, infliggendo $N1 danni da fuocogelo, rallentandone la velocità di movimento del $N2% e infliggendo altri $N3 danni da fuocogelo in $D1. Per questo incantesimo vale la più bassa tra le resistenze al gelo e al fuoco del bersaglio, e conta sia come danni da gelo sia come danni da fuoco.", nil, 0x3a219dc9, nil, "um" },
  [401736] = { "Ottieni l'abilità Raffica di Missili:\n\n$I1\nConferisce al tuo incantesimo Detonazione Arcana una probabilità del $N1%, e ai tuoi incantesimi Ira Arcana, Palla di Fuoco, Dardo di Gelo e Palla di Fuocogelo una probabilità del $N2%, di ridurre del $N3% la durata della canalizzazione del tuo prossimo incantesimo Missili Arcani, di ridurne il costo in mana del $N4% e di far partire i missili ogni $D1.", nil, 0x967fe765, nil, "um" },
  [401737] = { "Ottieni l'abilità Surriscaldamento:\n\n$I1\nDetonazione di Fuoco infligge sempre un colpo critico, può essere lanciata mentre lanci un altro incantesimo e non è soggetta al tempo di recupero globale, ma il suo tempo di recupero aumenta a $D1.", nil, 0x921647ac, nil, "um" },
  [401741] = { "Ottieni l'abilità Dita di Gelo:\n\n$I1\nConferisce ai tuoi effetti di raggelamento una probabilità del $N1% di farti ottenere l'effetto Dita di Gelo, che fa trattare i tuoi prossimi $N2 incantesimi lanciati come se il bersaglio fosse congelato. Dura $D1.", nil, 0xa7da2ad2, nil, "um" },
  [401743] = { "Ottieni l'abilità Rigenerazione:\n\n$I1\nCura il bersaglio di $N1 salute in $D1 e applica Temporal Beacon per $D2. \n\nTemporal Beacon\n$I2\nRegistra la posizione spazio-temporale del soggetto. Il $N4% di tutti i danni da arcano inflitti dall'incantatore viene convertito in cure cronomantiche su ciascuno dei bersagli attuali di Temporal Beacon dell'incantatore. Questa cura è ridotta del $N5% su sé stessi, e ridotta anche del $N6% quando i danni sono inflitti da incantesimi arcani che colpiscono più bersagli.", nil, 0x24c8a9d0, nil, "um" },
  [401744] = { "Ottieni l'abilità ⟦Living Flame=Fiamma Vivente⟧:\n\n$I1\nEvoca una fiamma di fuocoincanto che si muove verso il bersaglio, lasciando una scia di fuocoincanto. La scia infligge $N1 danni da fuocoincanto ogni secondo ai nemici vicini. Dura $D1.", nil, 0x8e90ef6f, nil, "um" },
  [401749] = { "Incidi sul tuo elmo la runa Serie Bollente:\n\n$I1\nI colpi critici non periodici di Palla di Fuoco, Palla di Fuocogelo, Detonazione di Fuoco e Bruciatura riducono del $N2% il tempo di lancio della tua prossima Pirosfera lanciata entro $D1, effetto che si accumula fino a $N3 volte. Detonazione di Fuoco conferisce un accumulo aggiuntivo ogni volta che infligge danni.", nil, 0xcad31fdf, nil, "um" },
  [401752] = { "Incidi sui tuoi stivali la runa Mente Fredda:\n\n$I1\nI tuoi incantesimi che infliggono danni da gelo con effetti di raggelamento hanno una probabilità del $N1% di rendere istantaneo e senza costo in mana il tuo prossimo incantesimo Palla di Fuoco, Dardo di Geloincanto, Balefire Bolt o Palla di Fuocogelo.", nil, 0x90851280, nil, "um" },
  [401754] = { "Incidi sul tuo elmo la runa Advanced Warding:\n\n$I1\nI tuoi incantesimi Scudo di Mana, Protezione dal Gelo e Guardia di Fuoco ora possono essere lanciati su qualsiasi bersaglio amico e assorbono il $N1% di danni in più, e Scudo di Mana consuma il $N2% di mana in meno per ogni danno assorbito. Inoltre, il tuo Remove Lesser Curse è sostituito da Remove Greater Curse.\n\n$I2\nRimuove $N3 maledizione e $N4 effetto magico dannoso da un bersaglio amico.", nil, 0xae017b08, nil, "um" },
  [401757] = { "Incidi sui tuoi guanti la runa ⟦Arcane Blast=Detonazione Arcana⟧:\n\n$I1\nInveste il bersaglio con un'esplosione di energia, infliggendo $N1 danni da arcano. Ogni volta che lanci ⟦Arcane Blast=Detonazione Arcana⟧, ottieni il $N2% del tuo Intelletto come danni magici e il costo in mana di ⟦Arcane Blast=Detonazione Arcana⟧ aumenta del $N3%. L'effetto si accumula fino a $N4 volte e dura $D1 dalla prima applicazione.", nil, 0x8e71b319, nil, "um" },
  [401759] = { "Incidi sulla tua armatura per il torso la runa Surriscaldamento:\n\n$I1\nAumenta del $N1% la probabilità di critico magico di tutti i tuoi incantesimi, ma i tuoi critici magici non periodici hanno ora un costo aggiuntivo in mana pari al $N2% del tuo mana base.", nil, 0x32623dd4, nil, "um" },
  [401760] = { "Incidi sui tuoi guanti la runa Lancia di Ghiaccio:\n\n$I1\nInfligge $N1 danni da gelo a un nemico bersaglio. Infligge il $N2% di danni in più ai bersagli congelati.", nil, 0x38968448, nil, "um" },
  [401761] = { "Incidi sui tuoi bracciali la runa Riavvolgimento Temporale:\n\n$I1\nIl tuo bersaglio attuale con Temporal Beacon guarisce istantaneamente tutti i danni subiti negli ultimi $N1 s. Inefficace sui bersagli che non avevano Temporal Beacon $N2 s prima.", nil, 0x5aca7557, nil, "um" },
  [401762] = { "Incidi sulla tua cintura la runa Palla di Fuocogelo:\n\n$I1\nScaglia un dardo di fuocogelo contro il nemico, infliggendo $N1 danni da fuocogelo, rallentandone la velocità di movimento del $N2% e infliggendo altri $N3 danni da fuocogelo in $D1. Per questo incantesimo vale la più bassa tra le resistenze al gelo e al fuoco del bersaglio, e conta sia come danni da gelo sia come danni da fuoco.", nil, 0x699fda74, nil, "um" },
  [401763] = { "Incidi sulla tua cintura la runa Raffica di Missili:\n\n$I1\nConferisce al tuo incantesimo Detonazione Arcana una probabilità del $N1%, e ai tuoi incantesimi Ira Arcana, Palla di Fuoco, Dardo di Gelo e Palla di Fuocogelo una probabilità del $N2%, di ridurre del $N3% la durata della canalizzazione del tuo prossimo incantesimo Missili Arcani, di ridurne il costo in mana del $N4% e di far partire i missili ogni $D1.", nil, 0x90adccfe, nil, "um" },
  [401764] = { "Incidi sul tuo mantello la runa Surriscaldamento:\n\n$I1\nDetonazione di Fuoco infligge sempre un colpo critico, può essere lanciata mentre lanci un altro incantesimo e non è soggetta al tempo di recupero globale, ma il suo tempo di recupero aumenta a $D1.", nil, 0x8ba49575, nil, "um" },
  [401765] = { "Incidi sulla tua armatura per il torso o sulla tua veste la runa Dita di Gelo:\n\n$I1\nConferisce ai tuoi effetti di raggelamento una probabilità del $N1% di farti ottenere l'effetto Dita di Gelo, che fa trattare i tuoi prossimi $N2 incantesimi lanciati come se il bersaglio fosse congelato. Dura $D1.", nil, 0xccde94fb, nil, "um" },
  [401767] = { "Incidi sulla tua armatura per il torso o sulla tua veste la runa Rigenerazione:\n\n$I1\nCura il bersaglio di $N1 salute in $D1 e applica Temporal Beacon per $D2. \n\nTemporal Beacon\n$I2\nRegistra la posizione spazio-temporale del soggetto. Il $N4% di tutti i danni da arcano inflitti dall'incantatore viene convertito in cure cronomantiche su ciascuno dei bersagli attuali di Temporal Beacon dell'incantatore. Questa cura è ridotta del $N5% su sé stessi, e ridotta anche del $N6% quando i danni sono inflitti da incantesimi arcani che colpiscono più bersagli.", nil, 0xf111a62e, nil, "um" },
  [401768] = { "Incidi sui tuoi gambali la runa ⟦Living Flame=Fiamma Vivente⟧:\n\n$I1\nEvoca una fiamma di fuocoincanto che si muove verso il bersaglio, lasciando una scia di fuocoincanto. La scia infligge $N1 danni da fuocoincanto ogni secondo ai nemici vicini. Dura $D1.", nil, 0x4d4c79bc, nil, "um" },
  [401847] = { "Combina con altri $N1 pezzi per ottenere la mappa completa.", nil, 0xdcc7f5cf, nil, "um" },
  [401859] = { "Pone sul bersaglio un incantesimo che lo cura di $N1 la prossima volta che subisce danni o riceve una cura non periodica. Quando avviene la cura, Preghiera di Guarigione salta su un membro del gruppo o dell'incursione entro $N2 m. Salta fino a $N3 volte e dura $D1 dopo ogni salto. Questo incantesimo può essere posto su un solo bersaglio alla volta per incantatore.", nil, 0x18d9951a, nil, "um" },
  [401863] = { "Pone sul bersaglio un incantesimo che lo cura la prossima volta che subisce danni. Quando avviene la cura, Preghiera di Guarigione salta su un membro del gruppo o dell'incursione entro $N1 m. Salta fino a $N2 volte e dura $D1 dopo ogni salto. Questo incantesimo può essere posto su un solo bersaglio alla volta.", nil, 0x5562ca1a, nil, "um" },
  [401877] = { "Pone sul bersaglio un incantesimo che lo cura la prossima volta che subisce danni o riceve una cura. Quando avviene la cura, Preghiera di Guarigione salta su un membro del gruppo o dell'incursione entro $N1 m. Salta fino a $N2 volte e dura $D1 dopo ogni salto. Questo incantesimo può essere posto su un solo bersaglio alla volta.", "Cura quando subisce danni o riceve cure.", 0x5aeb0cdd, 0xa73e48f0, "uu" },
  [401937] = { "Cura un bersaglio amico e l'incantatore di $N1. Minaccia ridotta.", nil, 0xda5be047, nil, "um" },
  [401946] = { "Cura di $N2 tutti i membri del gruppo del giocatore bersaglio che si trovano entro $N1 m da lui.", nil, 0x4267c87c, nil, "um" },
  [401955] = { "Una parola di oscuro vincolo che infligge $N1 danni da ombra al bersaglio. Se il bersaglio non viene ucciso da Parola d'Ombra: Morte, l'incantatore subisce danni pari al $N2% dei danni tentati contro il bersaglio.", nil, 0x51a0e84b, nil, "um" },
  [401956] = { nil, "All'interno di un blocco di ghiaccio che si rigenera rapidamente.", nil, 0xeedfae42, "mu" },
  [401962] = { "Una parola di oscuro vincolo che infligge danni da ombra al bersaglio. Se il bersaglio non viene ucciso da Parola d'Ombra: Morte, l'incantatore subisce danni pari a quelli inflitti al bersaglio.", nil, 0xdc462015, nil, "um" },
  [401969] = { "La tua ⟦Shadow Word: Pain=Parola d'Ombra: Dolore⟧ ora colpisce anche fino a $N1 bersagli aggiuntivi vicini entro $N2 m.", nil, 0xa6764800, nil, "um" },
  [401977] = { "Crea uno spirito d'ombra che attacca il bersaglio. L'incantatore riceve il $N1% di mana quando lo Spirito d'Ombra attacca. Dura $D1.", nil, 0x609469be, nil, "um" },
  [401981] = { nil, "Non è ancora abbastanza caldo! Più calore!", nil, 0x9987dc33, "mu" },
  [401984] = { "Gli attacchi in mischia dello Spirito d'Ombra sottraggono energia al bersaglio e la convertono in mana per il suo padrone.", "Converte i danni da ombra in mana.", 0x63a87b32, 0x41ef7edc, "uu" },
  [401988] = { "Gli attacchi in mischia dello Spirito d'Ombra sottraggono energia al bersaglio e la convertono in mana per il suo padrone.", nil, 0x63a87b32, nil, "um" },
  [401990] = { "Striscia tra le ombre fino al nemico bersaglio e aumenta del $N1% i danni inflitti dallo Spirito d'Ombra per $D1.", "Danni aumentati del $N1%.", 0x9c462814, 0xb557266a, "uu" },
})
